using UnityEngine;using UnityEditor;using Newtonsoft.Json;using System.Collections.Generic;public class Script{public static string Main(){var rows=new List<object>();foreach(var name in new[]{"Buff 6","Buff 1"}){var g=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Hovl Studio/RPG VFX Bundle/Prefabs/Magic buffs and hits/"+name+".prefab"));g.hideFlags=HideFlags.HideAndDontSave;try{var ps=(name=="Buff 6"?g.transform:g.transform.Find("Circles")).GetComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var em=ps.emission;em.enabled=false;ps.Simulate(0,false,true,false);var p=new ParticleSystem.Particle{position=new Vector3(1,2,3),velocity=new Vector3(.4f,.5f,.6f),startLifetime=1,remainingLifetime=1,startSize=1,randomSeed=1234};var buffer=new[]{p};ps.SetParticles(buffer,1);for(int i=0;i<50;i++){ps.Simulate(.01f,false,false,false);ps.GetParticles(buffer);p=buffer[0];rows.Add(new{name,step=i+1,position=new[]{p.position.x,p.position.y,p.position.z},velocity=new[]{p.totalVelocity.x,p.totalVelocity.y,p.totalVelocity.z}});}}finally{Object.DestroyImmediate(g);}}return JsonConvert.SerializeObject(rows);}}